96	export function materialize(
97	  seeds: SeedThread[],
98	  contactsById: Map<string, Contact>,
99	  now: number,
100	  idPrefix: string,
101	): Thread[] {
102	  const addr = (id: string): Address => {
103	    const c = id === 'me' ? ME : contactsById.get(id);
104	    if (!c) throw new Error(`Unknown contact id "${id}" in seed "${idPrefix}"`);
105	    return toAddress(c);
106	  };
107	
108	  return seeds.map((seed, ti) => {
109	    const threadId = `t_${idPrefix}${ti}`;
110	    const messages: Message[] = [];
111	    seed.messages.forEach((sm, mi) => {
112	      const prev = messages[mi - 1];
113	      const from = addr(sm.from);
114	      const defaultTo = sm.from === 'me' ? (prev && prev.from.email !== ME.email ? [prev.from] : []) : [addr('me')];
115	      const html = sm.html ?? md(sm.md ?? '');
116	      const attachments: Attachment[] = (sm.files ?? []).map(([name, size], ai) => ({
117	        id: `a_${threadId}_${mi}_${ai}`,
118	        name,
119	        size,
120	        mime: mimeFromName(name),
121	      }));
122	      const scheduledAt = sm.scheduledIn ? now + parseOffset(sm.scheduledIn) : undefined;
123	      messages.push({
124	        id: `m_${threadId}_${mi}`,
125	        threadId,
126	        from,
127	        to: sm.to ? sm.to.map(addr) : defaultTo,
128	        cc: (sm.cc ?? []).map(addr),
129	        bcc: (sm.bcc ?? []).map(addr),
130	        date: scheduledAt ? now : now - parseOffset(sm.ago),
131	        html,
132	        quoteHtml: prev && sm.quote !== false && !sm.draft && !sm.html ? quoteFor(prev) : undefined,
133	        text: htmlToText(html),
134	        attachments,
135	        unread: !!sm.unread,
136	        draft: !!sm.draft,
137	        scheduledAt,
138	        unsubscribe: sm.unsubscribe,
139	      });
140	    });
141	    messages.sort((a, b) => a.date - b.date);
142	    const hasIncoming = messages.some((m) => m.from.email !== ME.email && !m.draft);
143	    const trashed = !!seed.trashed;
144	    return {
145	      id: threadId,
146	      subject: seed.subject,
147	      messages,
148	      labelIds: seed.labels ?? [],
149	      category: seed.category ?? 'primary',
150	      inbox: hasIncoming && !seed.archived && !trashed && !seed.spam,
151	      starred: !!seed.starred,
152	      important: !!seed.important,
153	      trashed,
154	      trashedAt: trashed ? now - parseOffset(seed.trashedAgo ?? '1d') : undefined,
155	      spam: !!seed.spam,
156	      snoozedUntil: seed.snoozed ? now + parseOffset(seed.snoozed) : undefined,
157	    } satisfies Thread;
158	  });
