23	 * Tiny markdown dialect used by seed data and the auto-reply engine.
24	 * Supports paragraphs, `- ` and `1. ` lists, `> ` quotes, `# ` headings,
25	 * `---` rules, **bold**, *italic*, `code`, [links](url) and bare URLs.
26	 * A line consisting of `-- ` starts a signature block (rest of the text).
27	 */
28	export function md(src: string): string {
29	  const lines = src.replace(/\r\n/g, '\n').trim().split('\n');
30	  const out: string[] = [];
31	  let i = 0;
32	  const isBlank = (l: string) => l.trim() === '';
33	  while (i < lines.length) {
34	    const line = lines[i];
35	    if (isBlank(line)) {
36	      i++;
37	      continue;
38	    }
39	    if (line.trim() === '--' || line === '-- ') {
40	      const rest = lines.slice(i + 1).map((l) => inline(l.trim())).join('<br>');
41	      out.push(`<div class="sig">${rest}</div>`);
42	      break;
43	    }
44	    if (/^---+$/.test(line.trim())) {
45	      out.push('<hr>');
46	      i++;
47	      continue;
48	    }
49	    const h = /^(#{1,3})\s+(.*)$/.exec(line);
50	    if (h) {
51	      const level = h[1].length + 1;
52	      out.push(`<h${level}>${inline(h[2])}</h${level}>`);
53	      i++;
54	      continue;
55	    }
56	    if (/^>\s?/.test(line)) {
57	      const buf: string[] = [];
58	      while (i < lines.length && /^>\s?/.test(lines[i])) {
59	        buf.push(lines[i].replace(/^>\s?/, ''));
60	        i++;
61	      }
62	      out.push(`<blockquote>${md(buf.join('\n'))}</blockquote>`);
63	      continue;
64	    }
65	    if (/^\s*[-*]\s+/.test(line)) {
66	      const items: string[] = [];
67	      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
68	        items.push(`<li>${inline(lines[i].replace(/^\s*[-*]\s+/, ''))}</li>`);
69	        i++;
70	      }
71	      out.push(`<ul>${items.join('')}</ul>`);
72	      continue;
73	    }
74	    if (/^\s*\d+[.)]\s+/.test(line)) {
75	      const items: string[] = [];
76	      while (i < lines.length && /^\s*\d+[.)]\s+/.test(lines[i])) {
77	        items.push(`<li>${inline(lines[i].replace(/^\s*\d+[.)]\s+/, ''))}</li>`);
78	        i++;
79	      }
80	      out.push(`<ol>${items.join('')}</ol>`);
81	      continue;
82	    }
83	    const buf: string[] = [];
84	    while (
85	      i < lines.length &&
86	      !isBlank(lines[i]) &&
87	      !/^(>|#{1,3}\s|---+$|\s*[-*]\s+|\s*\d+[.)]\s+)/.test(lines[i]) &&
88	      lines[i].trim() !== '--'
89	    ) {
90	      buf.push(inline(lines[i]));
91	      i++;
92	    }
93	    out.push(`<p>${buf.join('<br>')}</p>`);
94	  }
95	  return out.join('');
