import type { MailState, Message, Thread } from './types';
import { DAY } from './dates';
import { inFolder, isMeAddr, isDelivered, isSnoozed, isUnread, threadDate, type Row } from './mail';
import type { SystemFolder } from './types';

export interface ParsedQuery {
  terms: string[];
  phrases: string[];
  exclude: string[];
  from: string[];
  to: string[];
  cc: string[];
  subject: string[];
  label: string[];
  in: string[];
  is: string[];
  has: string[];
  filename: string[];
  category: string[];
  before?: number;
  after?: number;
  olderThan?: number;
  newerThan?: number;
  larger?: number;
  smaller?: number;
}

const emptyQuery = (): ParsedQuery => ({
  terms: [],
  phrases: [],
