*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  font-family: var(--font-ui);
  font-size: 14px;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow: hidden;
  overscroll-behavior: none;
}

button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
input,
textarea,
select {
  font: inherit;
  color: inherit;
}
a {
  color: var(--accent);
}
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
button:focus-visible {
  outline-offset: 0;
}
::selection {
  background: color-mix(in srgb, var(--accent) 28%, transparent);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* scrollbars */
* {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--text-3) 40%, transparent) transparent;
}
::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--text-3) 35%, transparent);
  border: 3px solid transparent;
  background-clip: padding-box;
  border-radius: 8px;
}
::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--text-3) 55%, transparent);
  background-clip: padding-box;
  border: 3px solid transparent;
}

/* icons */
.icon {
  font-family: 'Material Symbols Outlined';
  font-weight: 400;
  font-style: normal;
  font-size: 24px;
  line-height: 1;
  letter-spacing: normal;
  text-transform: none;
  display: inline-block;
  white-space: nowrap;
  direction: ltr;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: 'liga';
  font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
  user-select: none;
  flex-shrink: 0;
  overflow: hidden;
  width: 1em;
  height: 1em;
}
.icon.fill {
  font-variation-settings: 'FILL' 1, 'wght' 400, 'GRAD' 0, 'opsz' 24;
}
.icon.sm {
  font-size: 18px;
}
.icon.xs {
  font-size: 16px;
}

/* buttons */
.icon-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  color: var(--text-2);
  transition: background 0.12s;
  flex-shrink: 0;
}
.icon-btn:hover:not(:disabled) {
  background: var(--hover);
}
.icon-btn:active:not(:disabled) {
  background: var(--hover-strong);
}
.icon-btn:disabled {
  opacity: 0.38;
  cursor: default;
}
.icon-btn.sm {
  width: 32px;
  height: 32px;
}
.icon-btn.sm .icon {
  font-size: 20px;
}
.icon-btn.active {
  background: var(--accent-container);
  color: var(--on-accent-container);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 40px;
  padding: 0 24px;
  border-radius: 20px;
  font-weight: 500;
  font-size: 14px;
  letter-spacing: 0.01em;
  transition: background 0.12s, box-shadow 0.12s;
  white-space: nowrap;
}
.btn.primary {
  background: var(--accent);
  color: var(--on-accent);
}
.btn.primary:hover:not(:disabled) {
  background: var(--accent-hover);
  box-shadow: var(--shadow-1);
}
.btn.text {
  color: var(--accent);
  padding: 0 12px;
}
.btn.text:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}
.btn.outline {
  border: 1px solid var(--line-strong);
  color: var(--text-2);
  padding: 0 20px;
}
.btn.outline:hover:not(:disabled) {
  background: var(--hover);
}
.btn.danger {
  background: var(--danger);
  color: #fff;
}
:root[data-theme='dark'] .btn.danger {
  color: #601410;
}
.btn:disabled {
  opacity: 0.45;
  cursor: default;
}

/* checkbox */
.cb {
  position: relative;
  display: inline-block;
  width: 18px;
  height: 18px;
  border: 2px solid var(--text-3);
  border-radius: 2px;
  flex-shrink: 0;
  transition: background 0.1s, border-color 0.1s;
  background: transparent;
}
.cb.checked,
.cb.indeterminate {
  background: var(--accent);
  border-color: var(--accent);
}
.cb.checked::after {
  content: '';
  position: absolute;
  left: 4px;
  top: 0.5px;
  width: 4px;
  height: 9px;
  border: solid var(--on-accent);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}
.cb.indeterminate::after {
  content: '';
  position: absolute;
  left: 2px;
  top: 6px;
  width: 10px;
  height: 2px;
  background: var(--on-accent);
}
.cb-hit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  flex-shrink: 0;
}
.cb-hit:hover {
  background: var(--hover);
}

/* avatar */
.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: #fff;
  font-family: var(--font-ui);
  font-weight: 500;
  flex-shrink: 0;
  user-select: none;
  text-transform: uppercase;
}

/* label chips */
.chip {
  --chip: #5f6368;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  height: 20px;
  padding: 0 6px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 500;
  line-height: 20px;
  white-space: nowrap;
  background: color-mix(in srgb, var(--chip) 17%, var(--surface));
  color: color-mix(in srgb, var(--chip) 65%, var(--text));
  flex-shrink: 0;
}
.chip.sys {
  background: var(--hover);
  color: var(--text-2);
}
.chip button {
  display: inline-flex;
  opacity: 0.7;
  margin-right: -2px;
  border-radius: 50%;
}
.chip button:hover {
  opacity: 1;
  background: var(--hover-strong);
}

mark {
  background: color-mix(in srgb, #f9c74f 55%, transparent);
  color: inherit;
  border-radius: 2px;
  padding: 0 1px;
}

/* popover / menu */
.popover {
  position: fixed;
  z-index: 1000;
  background: var(--surface-raised);
  border-radius: 8px;
  box-shadow: var(--shadow-2);
  padding: 8px 0;
  min-width: 160px;
  max-width: calc(100vw - 16px);
  max-height: calc(100vh - 16px);
  overflow: auto;
  color: var(--text);
  animation: pop 0.12s ease-out;
}
@keyframes pop {
  from {
    opacity: 0;
    transform: scale(0.97);
  }
}
.menu-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 32px;
  padding: 4px 16px;
  text-align: left;
  font-size: 14px;
  color: var(--text);
  white-space: nowrap;
}
.menu-item:hover:not(:disabled),
.menu-item.focus {
  background: var(--hover);
}
.menu-item:disabled {
  opacity: 0.45;
  cursor: default;
}
.menu-item .icon {
  color: var(--text-3);
  font-size: 20px;
}
.menu-item .menu-hint {
  margin-left: auto;
  padding-left: 24px;
  color: var(--text-3);
  font-size: 12px;
}
.menu-item .menu-check {
  margin-left: auto;
  color: var(--accent);
}
.menu-sep {
  height: 1px;
  background: var(--line);
  margin: 8px 0;
}
.menu-title {
  padding: 4px 16px 6px;
  font-size: 12px;
  color: var(--text-3);
  font-weight: 500;
}

/* toasts */
.toasts {
  position: fixed;
  left: 24px;
  bottom: 24px;
  z-index: 1300;
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: flex-start;
  pointer-events: none;
}
.toast {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 48px;
  min-width: 288px;
  max-width: min(560px, calc(100vw - 32px));
  padding: 6px 8px 6px 16px;
  background: #313033;
  color: #f4eff4;
  border-radius: 4px;
  box-shadow: var(--shadow-2);
  font-size: 14px;
  animation: toast-in 0.2s ease-out;
}
:root[data-theme='dark'] .toast {
  background: #e6e1e5;
  color: #313033;
}
.toast.error {
  background: #601410;
  color: #ffdad6;
}
.toast .toast-msg {
  flex: 1;
  padding-right: 8px;
}
.toast .toast-action {
  height: 36px;
  padding: 0 12px;
  border-radius: 4px;
  font-weight: 500;
  color: #a8c7fa;
  text-transform: none;
}
:root[data-theme='dark'] .toast .toast-action {
  color: #0b57d0;
}
.toast .toast-action:hover {
  background: rgba(168, 199, 250, 0.16);
}
.toast .toast-close {
  color: inherit;
  opacity: 0.8;
}
@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
}

/* dialogs */
.dialog-scrim {
  position: fixed;
  inset: 0;
  z-index: 1200;
  background: var(--scrim);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  animation: fade 0.15s ease-out;
}
@keyframes fade {
  from {
    opacity: 0;
  }
}
.dialog {
  background: var(--surface-raised);
  border-radius: 28px;
  box-shadow: var(--shadow-3);
  padding: 24px;
  width: 100%;
  max-width: 420px;
  max-height: calc(100vh - 32px);
  overflow: auto;
  animation: pop 0.15s ease-out;
}
.dialog h2 {
  margin: 0 0 16px;
  font-size: 24px;
  font-weight: 400;
  line-height: 32px;
}
.dialog p {
  margin: 0 0 24px;
  color: var(--text-2);
  line-height: 20px;
  font-family: var(--font-text);
}
.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 8px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 16px;
}
.field label {
  font-size: 12px;
  color: var(--text-3);
  font-weight: 500;
}
.input {
  height: 40px;
  padding: 0 12px;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  background: transparent;
  outline: none;
  width: 100%;
}
.input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}
select.input {
  padding-right: 8px;
}

