325	export function runSearch(state: MailState, query: string, now: number): SearchResult {
326	  const queries = parseQuery(query).filter((q) => !isEmptyQuery(q));
327	  if (!queries.length) return { rows: [], highlight: [] };
328	  const ctx: SearchCtx = { state, now };
329	  const rows: Row[] = [];
330	  for (const t of Object.values(state.threads)) {
331	    if (matchThread(t, queries, ctx)) rows.push({ key: t.id, thread: t });
332	  }
333	  rows.sort((a, b) => threadDate(b.thread) - threadDate(a.thread));
334	  const highlight = new Set<string>();
335	  for (const q of queries) {
336	    for (const x of [...q.terms, ...q.phrases, ...q.subject]) highlight.add(x);
337	  }
338	  return { rows, highlight: [...highlight].filter((h) => h.length > 0).sort((a, b) => b.length - a.length) };
339	}
