342	export function searchSnippet(t: Thread, highlight: string[], max = 150): string {
343	  if (!highlight.length) return '';
344	  const msgs = t.messages.filter(isDelivered).slice().reverse();
345	  for (const m of msgs) {
346	    const text = m.text.replace(/\s+/g, ' ');
347	    const lower = text.toLowerCase();
348	    for (const h of highlight) {
349	      const i = lower.indexOf(h);
350	      if (i >= 0) {
351	        const start = Math.max(0, i - 40);
352	        return (start > 0 ? '…' : '') + text.slice(start, start + max);
353	      }
354	    }
355	  }
356	  return '';
357	}
