391	export function buildQueryFromAdvanced(f: AdvancedFields): string {
392	  const parts: string[] = [];
393	  if (f.from.trim()) parts.push(`from:${quoteIfNeeded(f.from.trim())}`);
394	  if (f.to.trim()) parts.push(`to:${quoteIfNeeded(f.to.trim())}`);
395	  if (f.subject.trim()) parts.push(`subject:${quoteIfNeeded(f.subject.trim())}`);
396	  if (f.has.trim()) parts.push(f.has.trim());
397	  if (f.exclude.trim()) {
398	    for (const w of f.exclude.trim().split(/\s+/)) parts.push(`-${w}`);
399	  }
400	  if (f.size && f.sizeValue.trim()) parts.push(`${f.size}:${f.sizeValue.trim()}${f.sizeUnit}`);
401	  if (f.date) {
402	    const center = parseDateOperand(f.date);
403	    if (center !== undefined) {
404	      const span = parseDuration(f.within || '1d') ?? DAY;
405	      const fmt = (ts: number) => {
406	        const d = new Date(ts);
407	        return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`;
408	      };
409	      parts.push(`after:${fmt(center - span)}`, `before:${fmt(center + span + DAY)}`);
410	    }
411	  }
412	  if (f.scope && f.scope !== 'all') parts.push(`in:${f.scope}`);
413	  if (f.attachment) parts.push('has:attachment');
414	  return parts.join(' ');
415	}
