import type { MailState, Message, Thread } from './types';
import { DAY } from './dates';
import { inFolder, isMeAddr, isDelivered, isSnoozed, isUnread, threadDate, type Row } from './mail';
import type { SystemFolder } from './types';

export interface ParsedQuery {
  terms: string[];
  phrases: string[];
  exclude: string[];
  from: string[];
  to: string[];
  cc: string[];
  subject: string[];
  label: string[];
  in: string[];
  is: string[];
  has: string[];
  filename: string[];
  category: string[];
  before?: number;
  after?: number;
  olderThan?: number;
  newerThan?: number;
  larger?: number;
  smaller?: number;
}

const emptyQuery = (): ParsedQuery => ({
  terms: [],
  phrases: [],
  exclude: [],
  from: [],
  to: [],
  cc: [],
  subject: [],
  label: [],
  in: [],
  is: [],
  has: [],
  filename: [],
  category: [],
});

const TOKEN_RE = /(-?)(?:([a-z_]+):)?(?:"([^"]*)"|(\S+))/gi;

export function parseDateOperand(v: string): number | undefined {
  const m = /^(\d{4})[/-](\d{1,2})[/-](\d{1,2})$/.exec(v.trim());
  if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])).getTime();
  const t = Date.parse(v);
  return Number.isNaN(t) ? undefined : t;
}

export function parseDuration(v: string): number | undefined {
  const m = /^(\d+)([dwmy])$/i.exec(v.trim());
  if (!m) return undefined;
  const n = Number(m[1]);
  switch (m[2].toLowerCase()) {
    case 'd':
      return n * DAY;
    case 'w':
      return n * 7 * DAY;
    case 'm':
      return n * 30 * DAY;
    default:
      return n * 365 * DAY;
  }
}

export function parseSize(v: string): number | undefined {
  const m = /^(\d+(?:\.\d+)?)\s*([kmg]?)b?$/i.exec(v.trim());
  if (!m) return undefined;
  const mult = { '': 1, k: 1024, m: 1024 ** 2, g: 1024 ** 3 }[m[2].toLowerCase() as '' | 'k' | 'm' | 'g'];
  return Math.round(parseFloat(m[1]) * mult);
}

function parseOne(src: string): ParsedQuery {
  const q = emptyQuery();
  let m: RegExpExecArray | null;
  TOKEN_RE.lastIndex = 0;
  while ((m = TOKEN_RE.exec(src))) {
    const neg = m[1] === '-';
    const op = m[2]?.toLowerCase();
    const quoted = m[3] !== undefined;
    const value = (m[3] ?? m[4] ?? '').trim();
    if (!value) continue;
    const lower = value.toLowerCase();
    if (!op) {
      if (neg) q.exclude.push(lower);
      else if (quoted) q.phrases.push(lower);
      else q.terms.push(lower);
      continue;
    }
    switch (op) {
      case 'from':
        q.from.push(lower);
        break;
      case 'to':
        q.to.push(lower);
        break;
      case 'cc':
        q.cc.push(lower);
        break;
      case 'subject':
        q.subject.push(lower);
        break;
      case 'label':
        q.label.push(lower);
        break;
      case 'in':
        q.in.push(lower);
        break;
      case 'is':
        q.is.push(lower);
        break;
      case 'has':
        q.has.push(lower);
        break;
      case 'filename':
        q.filename.push(lower);
        break;
      case 'category':
        q.category.push(lower);
        break;
      case 'before':
